using PropFlow.Web.Client.Features.Apartment.Models;
using PropFlow.Web.Client.Services.Api;
namespace PropFlow.Web.Client.Features.Apartment.Services;
public interface IApartmentApiClient { Task<ApiResult<PagedApartmentsResponse>> ListAsync(string? search,string? status,int? floorNumber=null,Guid? apartmentUnitTypeId=null,string? occupancy=null,int page=1,int pageSize=10); Task<ApiResult<IReadOnlyList<ApartmentUnitTypeResponse>>> UnitTypesAsync(); Task<ApiResult<ApartmentUnitTypeResponse>> CreateUnitTypeAsync(CreateApartmentUnitTypeRequest request); Task<ApiResult<ApartmentUnitTypeResponse>> UpdateUnitTypeAsync(Guid id,UpdateApartmentUnitTypeRequest request); Task<ApiResult<EmptyResponse>> DeleteUnitTypeAsync(Guid id); Task<ApiResult<ApartmentResponse>> GetAsync(Guid id); Task<ApiResult<IReadOnlyList<ResidentApartmentSelfItem>>> MeAsync(); Task<ApiResult<IReadOnlyList<ApartmentOwnershipHistoryItem>>> OwnershipHistoryAsync(Guid id); Task<ApiResult<ApartmentResponse>> CreateAsync(CreateApartmentRequest request); Task<ApiResult<EmptyResponse>> UpdateAsync(Guid id,UpdateApartmentRequest request); Task<ApiResult<EmptyResponse>> SetStatusAsync(Guid id,string status); Task<ApiResult<IReadOnlyList<ResidentLookupItem>>> OwnerCandidatesAsync(Guid apartmentId,string? search); Task<ApiResult<IReadOnlyList<ApartmentOwnershipCandidate>>> OwnershipCandidatesAsync(Guid ownerResidentId,string? search); Task<ApiResult<EmptyResponse>> AddOwnerAsync(Guid id, ChangeApartmentOwnerRequest request); Task<ApiResult<EmptyResponse>> EndOwnershipAsync(Guid id,Guid ownershipId,EndApartmentOwnershipRequest request); }
public sealed class ApartmentApiClient(AuthenticatedApiClient api):IApartmentApiClient { public Task<ApiResult<PagedApartmentsResponse>> ListAsync(string? s,string? status,int? floor=null,Guid? typeId=null,string? occupancy=null,int p=1,int pageSize=10)=>api.SendAsync<PagedApartmentsResponse>(HttpMethod.Get,$"api/v1/apartments?pageIndex={p}&pageSize={pageSize}"+(string.IsNullOrWhiteSpace(s)?"":$"&search={Uri.EscapeDataString(s)}")+(string.IsNullOrWhiteSpace(status)?"":$"&status={status}")+(floor.HasValue?$"&floorNumber={floor}":"")+(typeId.HasValue?$"&apartmentUnitTypeId={typeId}":"")+(string.IsNullOrWhiteSpace(occupancy)?"":$"&occupancy={occupancy}")); public Task<ApiResult<IReadOnlyList<ApartmentUnitTypeResponse>>> UnitTypesAsync()=>api.SendAsync<IReadOnlyList<ApartmentUnitTypeResponse>>(HttpMethod.Get,"api/v1/apartment-unit-types"); public Task<ApiResult<ApartmentUnitTypeResponse>> CreateUnitTypeAsync(CreateApartmentUnitTypeRequest r)=>api.SendAsync<ApartmentUnitTypeResponse>(HttpMethod.Post,"api/v1/apartment-unit-types",r); public Task<ApiResult<ApartmentUnitTypeResponse>> UpdateUnitTypeAsync(Guid id,UpdateApartmentUnitTypeRequest r)=>api.SendAsync<ApartmentUnitTypeResponse>(HttpMethod.Put,$"api/v1/apartment-unit-types/{id}",r); public Task<ApiResult<EmptyResponse>> DeleteUnitTypeAsync(Guid id)=>api.SendAsync<EmptyResponse>(HttpMethod.Delete,$"api/v1/apartment-unit-types/{id}"); public Task<ApiResult<ApartmentResponse>> GetAsync(Guid id)=>api.SendAsync<ApartmentResponse>(HttpMethod.Get,$"api/v1/apartments/{id}"); public Task<ApiResult<IReadOnlyList<ResidentApartmentSelfItem>>> MeAsync()=>api.SendAsync<IReadOnlyList<ResidentApartmentSelfItem>>(HttpMethod.Get,"api/v1/apartments/me"); public Task<ApiResult<IReadOnlyList<ApartmentOwnershipHistoryItem>>> OwnershipHistoryAsync(Guid id)=>api.SendAsync<IReadOnlyList<ApartmentOwnershipHistoryItem>>(HttpMethod.Get,$"api/v1/apartments/{id}/ownership-history"); public Task<ApiResult<ApartmentResponse>> CreateAsync(CreateApartmentRequest r)=>api.SendAsync<ApartmentResponse>(HttpMethod.Post,"api/v1/apartments",r); public Task<ApiResult<EmptyResponse>> UpdateAsync(Guid id,UpdateApartmentRequest r)=>api.SendAsync<EmptyResponse>(HttpMethod.Put,$"api/v1/apartments/{id}",r); public Task<ApiResult<EmptyResponse>> SetStatusAsync(Guid id,string s)=>api.SendAsync<EmptyResponse>(HttpMethod.Patch,$"api/v1/apartments/{id}/status",new SetApartmentStatusRequest{Status=s}); public Task<ApiResult<IReadOnlyList<ResidentLookupItem>>> OwnerCandidatesAsync(Guid id,string? s)=>api.SendAsync<IReadOnlyList<ResidentLookupItem>>(HttpMethod.Get,$"api/v1/apartments/owner-candidates?apartmentId={id}"+(string.IsNullOrWhiteSpace(s)?"":$"&search={Uri.EscapeDataString(s)}")); public Task<ApiResult<IReadOnlyList<ApartmentOwnershipCandidate>>> OwnershipCandidatesAsync(Guid id,string? s)=>api.SendAsync<IReadOnlyList<ApartmentOwnershipCandidate>>(HttpMethod.Get,$"api/v1/apartments/ownership-candidates?ownerResidentId={id}"+(string.IsNullOrWhiteSpace(s)?"":$"&search={Uri.EscapeDataString(s)}")); public Task<ApiResult<EmptyResponse>> AddOwnerAsync(Guid id,ChangeApartmentOwnerRequest r)=>api.SendAsync<EmptyResponse>(HttpMethod.Post,$"api/v1/apartments/{id}/owners",r); public Task<ApiResult<EmptyResponse>> EndOwnershipAsync(Guid id,Guid ownerId,EndApartmentOwnershipRequest r)=>api.SendAsync<EmptyResponse>(HttpMethod.Patch,$"api/v1/apartments/{id}/owners/{ownerId}/end",r); }
